SELECT ?codeLabel (COUNT(DISTINCT ?g) AS ?patientCount) WHERE {
  GRAPH ?g {
    ?r a sphn:MedicalProcedure .
    ?r sphn:hasCode ?c .
    ?c isa icd-10-gm:C91
  }
  GRAPH <https://biomedit.ch/rdf/sphn-resource/global> {
    ?c rdfs:label ?codeLabel
  }
}
GROUP BY ?codeLabel
ORDER BY DESC(?patientCount)
LIMIT 10

SELECT ?routeLabel (COUNT(DISTINCT ?g) AS ?eventCount) WHERE {
  GRAPH ?g {
    ?r a sphn:DrugAdministrationEvent .
    ?r sphn:hasAdministrationRouteCode ?c
  }
  GRAPH <https://biomedit.ch/rdf/sphn-resource/global> {
    ?c rdfs:label ?routeLabel
  }
}
GROUP BY ?routeLabel
ORDER BY DESC(?eventCount)
LIMIT 10

SELECT ?typeCodeValue (COUNT(DISTINCT ?g) AS ?patientCount) WHERE {
  GRAPH ?g {
    ?r a sphn:CopyNumberVariation .
    ?r sphn:hasTypeCode ?c
  }
}
GROUP BY ?typeCodeValue
ORDER BY DESC(?patientCount)

SELECT ?stopReasonLabel (COUNT(DISTINCT ?g) AS ?eventCount) WHERE {
  GRAPH ?g {
    ?r a sphn:DrugAdministrationEvent .
    ?r sphn:hasReasonToStopCode ?c
  }
  GRAPH <https://biomedit.ch/rdf/sphn-resource/global> {
    ?c rdfs:label ?stopReasonLabel
  }
}
GROUP BY ?stopReasonLabel
ORDER BY DESC(?eventCount)
LIMIT 10

SELECT ?algorithmValue (COUNT(DISTINCT ?g) AS ?patientCount) WHERE {
  GRAPH ?g {
    ?r a sphn:Hash .
    ?r sphn:hasAlgorithm ?alg
  }
  BIND(str(?alg) AS ?algorithmValue)
}
GROUP BY ?algorithmValue
ORDER BY DESC(?patientCount)

SELECT (COUNT(DISTINCT ?g) AS ?count) WHERE {
  GRAPH ?g {
    ?r a sphn:ResuscitationDirective .
    ?r sphn:hasCode ?c .
    FILTER(?c = snomed:304253006)
  }
}

SELECT (COUNT(DISTINCT ?g) AS ?count) WHERE {
  GRAPH ?g {
    ?r a sphn:Circumference .
    ?r sphn:hasQuantity ?q .
    ?q sphn:hasValue ?v .
  }
}

SELECT (COUNT(DISTINCT ?g) AS ?count) WHERE {
  GRAPH ?g {
    ?r a sphn:BodyHeightMeasurement .
    ?r sphn:hasMethodCode ?c .
    FILTER(?c = snomed:287539003)
  }
}

SELECT (SUM(bif:datediff("day", ?start, ?end)) AS ?totalDays) WHERE {
  GRAPH ?g {
    ?adm a sphn:AdministrativeCase .
    ?adm sphn:hasAdmissionDateTime ?start .
    ?adm sphn:hasDischargeDateTime ?end
  }
}

SELECT ?morphology (COUNT(DISTINCT ?g) AS ?patientCount)
WHERE {
  GRAPH ?g {
    ?r a sphn:MicrobiologyMicroscopyResult ;
       sphn:hasStainingResultCode ?stainCode ;
       sphn:hasCellMorphology ?morphology .
    ?stainCode a snomed:10828004 .
  }
}
GROUP BY ?morphology

SELECT ?labTestType (COUNT(?r) AS ?eventCount)
WHERE {
  GRAPH ?g {
    ?r a sphn:LabTestEvent ;
       sphn:hasLabTest ?labTest .
    ?labTest a ?labTestType .
  }
}
GROUP BY ?labTestType

SELECT DISTINCT ?patientId
WHERE {
  GRAPH ?g {
    ?patientId a sphn:Patient .
    ?record a sphn:ClinicalEvent ;
            sphn:hasCode ?code .
    FILTER(?code isa icd-10-gm:I63)
  }
}

SELECT DISTINCT ?patientId
WHERE {
  GRAPH ?g {
    ?patientId a sphn:Patient .
    ?insurance a sphn:InsuranceStatus ;
               sphn:hasCoverageType sphn-individual:Foreign .
    OPTIONAL { ?insurance sphn:hasSubjectPseudoIdentifier ?patientId }
    FILTER(!BOUND(?patientId))
  } UNION {
    GRAPH ?g {
      ?patientId a sphn:Patient .
      ?insurance a sphn:InsuranceStatus ;
                 sphn:hasCoverageType sphn-individual:Foreign ;
                 sphn:hasSubjectPseudoIdentifier ?patientId .
    }
  }
}

SELECT DISTINCT ?patientId
WHERE {
  GRAPH ?g {
    ?patientId a sphn:Patient .
    ?location a sphn:Location ;
              sphn:hasTypeCode snomed:216364003 .
    OPTIONAL { ?location sphn:hasDataProvider ?provider }
  }
}

SELECT DISTINCT ?patientId
WHERE {
  GRAPH ?g {
    ?patientId a sphn:Patient .
    ?variant a sphn:VariantNotation .
    OPTIONAL { ?variant sphn:hasCodingSystemAndVersion ?sys }
  }
}

SELECT DISTINCT ?patientId
WHERE {
  GRAPH ?g1 {
    ?patientId a sphn:Patient .
    ?protein a sphn:Protein ;
             sphn:hasCode ?code .
  }
  GRAPH ?g2 {
    ?insurance a sphn:InsuranceStatus ;
               sphn:hasCoverageType sphn-individual:Private .
    OPTIONAL { ?insurance sphn:hasSubjectPseudoIdentifier ?pid }
    FILTER(BOUND(?pid) && ?pid = ?patientId)
  }
}

SELECT (COUNT(DISTINCT ?g) AS ?count)
WHERE {
  GRAPH ?g {
    ?patient a sphn:Patient .

    # Resistant Antimicrobial
    ?suscept a sphn:AntimicrobialSusceptibilityResult .
    ?suscept sphn:hasSubjectPseudoIdentifier ?patient .
    ?suscept sphn:hasCode ?resistCode .
    ?resistCode isa snomed:30714006

    # Tumor Stage Assessment exists but has no data provider
    ?event a sphn:TumorStageAssessmentEvent .
    ?event sphn:hasSubjectPseudoIdentifier ?patient .
    FILTER NOT EXISTS {
      ?event sphn:hasDataProvider ?provider
    }
  }
}

SELECT COUNT(DISTINCT ?g) {
  GRAPH ?g {
    ?a a sphn:AdministrativeCase .
    ?a sphn:hasAdmissionDateTime ?date .
    FILTER(YEAR(?date) = 1960 && MONTH(?date) = 3 && DAY(?date) = 9)

    OPTIONAL {
      ?r a sphn:TobaccoExposure ;
         sphn:hasTypeCode ?tc .
      FILTER(?tc = snomed:702979003)
    }

    ?drug a sphn:DrugAdministrationEvent .
    OPTIONAL {
      ?drug sphn:hasReasonToStopCode ?rc .
      FILTER(?rc IN (snomed:31438003, snomed:395009001))
    }
  }
}

